            },
            { mapID = 118, x = 0.6859999999999999, y = 0.209, step = 6, label = "Squire Danny - Valiant's Challenge" },
            { mapID = 118, x = 0.762, y = 0.19, step = 7, label = "Jaelyne Evensong - championship turn-in" },
            { mapID = 116, x = 0.605, y = 0.515, step = 4, label = "Blade Fit - lip balm, /kiss frogs, talk to Maiden" },
            { mapID = 127, x = 0.12, y = 0.16, step = 4, label = "Worthy Weapon - FOUR Winter Hyacinths" },
            {
                mapID = 115,
                x = 0.9309999999999999,
                y = 0.259,
                step = 4,
                label = "Worthy Weapon - use flowers in circle, LOOT sword",
            },
            {
                mapID = 127,
                x = 0.555,
                y = 0.7490000000000001,
                step = 4,
                label = "Edge of Winter - kill Lord Everblaze, loot ember",
            },
            {
                mapID = 117,
                x = 0.42200000000000004,
                y = 0.196,
                step = 4,
                label = "Edge of Winter - use ember on frozen Maiden",
            },
        },
        tips = "The usual five-seal daily total makes this a multi-reset stage. If a newly chosen city's dailies are absent, the shared quests may already have been completed that day for the previous city.",
        sources = {
            "https://www.wowhead.com/achievement=2777#comments:id=2291684",
