    [2782] = {
        achievementId = 2782,
        name = "Champion of the Alliance",
        category = "Argent Tournament",
        sourceType = "Achievement",
        source = "Champion of the Alliance",
        acquisition = "Difficulty: Hard - Champion all five home cities through consecutive daily training stages; Exalted variants add all required reputations.\n\n1. Enrol and reach Valiant through the Argent Aspiration/Argent Valor guides. Finish the first city offered to your character, then choose the other cities one at a time. The five Alliance cities are Darnassus, Exodar, Gnomeregan, Ironforge and Stormwind.\n\n2. For EACH city, accept its Valiant invitation, earn twenty-five Valiant's Seals through its dailies, turn in The Valiant's Charge, and defeat Squire Danny's Argent Champion for The Valiant's Challenge. Return for that city's final hand-in before starting another city. Use the individual city guides for the full weapon errands and mounted tasks.\n\n3. Continue unlocked Champion dailies alongside the currently selected city's Valiant work. Changing cities keeps your previous Champion ranks. Shared dailies already completed that day do not necessarily reappear for the new city; continue after reset.\n\n4. Check all five Champion criteria for the meta. City Exalted reputations are not required for this basic Champion meta.",
        stepCount = 4,
        waypoints = {
            { mapID = 118, x = 0.762, y = 0.19, step = 2, label = "Jaelyne Evensong - Darnassus" },
            { mapID = 118, x = 0.76, y = 0.192, step = 2, label = "Colosos - Exodar" },
            { mapID = 118, x = 0.764, y = 0.198, step = 2, label = "Ambrose Boltspark - Gnomeregan" },
            { mapID = 118, x = 0.764, y = 0.19399999999999998, step = 2, label = "Lana Stouthammer - Ironforge" },
            { mapID = 118, x = 0.764, y = 0.192, step = 2, label = "Marshal Jacob Alerius - Stormwind" },
            { mapID = 118, x = 0.6859999999999999, y = 0.209, step = 2, label = "Squire Danny - city Valiant's Challenge" },
        },
        tips = "Old advice to withhold the fifth championship for daily gold conflicts with completing this achievement. Finish all required city turn-ins. Gilneas, Bilgewater and allied-race cities are not extra criteria.",
        sources = {
            "https://www.wowhead.com/achievement=2782#comments",
            "https://www.wowhead.com/achievement=2788#comments:id=702657",
