    [2788] = {
        achievementId = 2788,
        name = "Champion of the Horde",
        category = "Argent Tournament",
        sourceType = "Achievement",
        source = "Champion of the Horde",
        acquisition = "Difficulty: Hard - Champion all five home cities through consecutive daily training stages; Exalted variants add all required reputations.\n\n1. Enrol and reach Valiant through the Argent Aspiration/Argent Valor guides. Finish the first city offered to your character, then choose the other cities one at a time. The five Horde cities are Orgrimmar, Sen'jin, Silvermoon City, Thunder Bluff and the Undercity.\n\n2. For EACH city, accept its Valiant invitation, earn twenty-five Valiant's Seals through its dailies, turn in The Valiant's Charge, and defeat Squire Danny's Argent Champion for The Valiant's Challenge. Return for that city's final hand-in before starting another city. Use the individual city guides for the full weapon errands and mounted tasks.\n\n3. Continue unlocked Champion dailies alongside the currently selected city's Valiant work. Changing cities keeps your previous Champion ranks. Shared dailies already completed that day do not necessarily reappear for the new city; continue after reset.\n\n4. Check all five Champion criteria for the meta. City Exalted reputations are not required for this basic Champion meta.",
        stepCount = 4,
        waypoints = {
            { mapID = 118, x = 0.764, y = 0.244, step = 2, label = "Mokra the Skullcrusher - Orgrimmar" },
            { mapID = 118, x = 0.76, y = 0.244, step = 2, label = "Zul'tore - Sen'jin" },
            { mapID = 118, x = 0.764, y = 0.23800000000000002, step = 2, label = "Eressea Dawnsinger - Silvermoon City" },
            { mapID = 118, x = 0.762, y = 0.244, step = 2, label = "Runok Wildmane - Thunder Bluff" },
