    [2836] = {
        achievementId = 2836,
        name = "Lance a Lot",
        category = "Argent Tournament",
        sourceType = "Achievement",
        source = "Lance a Lot",
        acquisition = "Difficulty: Medium - Reach Valiant and defeat all ten racial riders using the tournament vehicle's combat abilities.\n\n1. Reach Valiant and accept The Grand Melee. Keep it in your log while working through the TEN racial riders, including both factions. Equip the lance and mount a tournament steed.\n\n2. Before each challenge, stack Defend to three. Challenge an uncredited Valiant in the Alliance ring (75, 18): Darnassus, Exodar, Gnomeregan, Ironforge and Stormwind. Keep the daily unturned-in even after its required marks are collected so you can continue challenging.\n\n3. Stay in melee using Thrust until the rider retreats. Charge as soon as you have range, then Shield-Breaker while turning back toward them. Refresh lost Defend stacks. Charging first avoids delaying your charge while the enemy prepares theirs.\n\n4. Repeat for the five Horde Valiants in their ring (75, 26): Orgrimmar, Sen'jin, Silvermoon, Thunder Bluff and Undercity. Different rider styles may need more circling and Shield-Breaker/Charge opportunities, especially Exodar/Thunder Bluff.\n\n5. Check all ten race ticks before turning in The Grand Melee. If you handed it in before finishing the list, return when that daily is available again. This achievement is NPC jousting, while Tilted! needs a player duel.",
        stepCount = 5,
        waypoints = {
            { mapID = 118, x = 0.75, y = 0.18, step = 2, label = "Alliance Valiants - all five cities" },
            { mapID = 118, x = 0.75, y = 0.18, step = 3, label = "Charge, then Shield-Breaker; maintain Defend" },
            { mapID = 118, x = 0.75, y = 0.26, step = 4, label = "Horde Valiants - all five cities" },
        },
        tips = "You do not have to discard daily marks or abandon/reaccept the quest between riders.",
