    [3217] = {
        achievementId = 3217,
        name = "Chasing Marcia",
        category = "Professions",
        sourceType = "Achievement",
        source = "Chasing Marcia",
        acquisition = "Difficulty: Medium - Complete each randomly offered Dalaran cooking or fishing daily over multiple resets.\n\n1. Visit Marcia Chase at Northrend Dalaran's Eventide fountain (52.6, 64.8), learn Northrend Fishing and accept today's daily. Complete each of her FIVE different daily quests over multiple resets; you cannot select all five on one day.\n\n2. Jewel Of The Sewers: fish open water in the Northrend Underbelly, for example the Cantrips & Crows dock (44.0, 65.0), until you catch Corroded Jewelry. Return it to Marcia.\n\n3. Disarmed!: fish the water outside Violet Hold (65.0, 61.0), catch and OPEN the Bloated Slippery Eel, then bring its Severed Arm to Olisarra the Kind at First to Your Aid (37.4, 36.6). This turn-in is not at Marcia.\n\n4. The Ghostfish: fish open water at River's Heart in Sholazar Basin (50.1, 61.5). EAT the Phantom Ghostfish within one minute, while still there, so its mystery credits. Then return to Marcia.\n\n5. Blood Is Thicker: in Borean Tundra kill a beast for the blood effect, then enter fishable water such as Lake Kum'uya (53.0, 44.0). Fish five Bloodtooth Frenzies from the resulting blood pool and return them to Marcia.\n\n6. Dangerously Delicious: fish ten Terrorfish from open water in OUTDOOR Wintergrasp, for example its eastern lake (71.0, 42.0). Return them to Marcia. You do not need to queue for the battleground or win its fortress.\n\n7. Keep checking after daily resets until all five turn-ins credit. Opening the Bag of Fishing Treasures is useful for rewards but does not replace completing a missing daily. Use the Northrend quest giver, not her Legion counterpart.",
        stepCount = 7,
        waypoints = {
            { mapID = 125, x = 0.526, y = 0.648, step = 1, label = "Marcia Chase - one random daily per day" },
            { mapID = 126, x = 0.44, y = 0.65, step = 2, label = "Jewel Of The Sewers - Corroded Jewelry" },
            { mapID = 125, x = 0.65, y = 0.61, step = 3, label = "Disarmed! - fish and open Bloated Slippery Eel" },
            { mapID = 125, x = 0.374, y = 0.366, step = 3, label = "Olisarra - deliver Severed Arm" },
            { mapID = 119, x = 0.501, y = 0.615, step = 4, label = "River's Heart - eat Phantom Ghostfish promptly" },
            { mapID = 114, x = 0.53, y = 0.44, step = 5, label = "Lake Kum'uya - create and fish blood pool" },
            { mapID = 123, x = 0.71, y = 0.42, step = 6, label = "Outdoor Wintergrasp - Terrorfish" },
        },
        sources = {
            "https://www.wowhead.com/achievement=3217#comments:id=1633275",
