    [3218] = {
        achievementId = 3218,
        name = "Turtles All the Way Down",
        category = "Professions",
        sourceType = "Achievement",
        source = "Turtles All the Way Down",
        acquisition = "Difficulty: Hard - Fish eligible pools until the very rare Sea Turtle catch appears; completion has no fixed attempt count.\n\n1. Learn Fishing and choose a circuit of visible eligible fishing pools. Enable Find Fish if learned. Northrend Nettlefish and Fangtooth Herring pools are useful because they also advance other fishing achievements.\n\n2. Start at Bittertide Lake in Sholazar Basin (38.0, 39.0). Cast inside each Nettlefish school until it disappears, then move to the next. Fishing the lake's ordinary open water does not give the same turtle opportunity.\n\n3. If pools are empty or crowded, switch to Howling Fjord's inland Fangtooth Herring schools, for example near 48.0, 39.0. This also gives a chance at the Dark Herring needed for One That Didn't Get Away outside this expansion catalogue.\n\n4. Continue pool fishing, loot every catch and keep bag space. When Sea Turtle (46109) appears, loot its original item before recasting and learn the mount. Check the achievement as well as the Mount Journal.",
        stepCount = 4,
        waypoints = {
            { mapID = 119, x = 0.38, y = 0.39, step = 2, label = "Bittertide Lake - Nettlefish pool circuit" },
            { mapID = 117, x = 0.48, y = 0.39, step = 3, label = "Howling Fjord lakes - Fangtooth Herring alternate" },
        },
        tips = "Eligible pools in later expansions also provide surviving Retail routes. This is a rare catch without a guaranteed number of casts; fountain or sewer open-water fishing for coins/rat is a different farm.",
        sources = {
            "https://www.wowhead.com/achievement=3218#comments:id=929176",
            "https://www.wowhead.com/achievement=3218#comments:id=1900057",
            "https://www.wowhead.com/achievement=3218#comments:id=1607166",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=3218",
        sourceURL = "https://www.wowhead.com/achievement=3218#comments",
        difficultyReason = "Fish eligible pools until the very rare Sea Turtle catch appears; completion has no fixed attempt count.",
        difficulty = "hard",
    },
    [3296] = {
        achievementId = 3296,
        name = "Cooking with Style",
        category = "Professions",
        sourceType = "Achievement",
        source = "Cooking with Style",
        acquisition = "Difficulty: Hard - Earn and spend one hundred Epicurean's Awards on the Chef's Hat; regular income is limited by daily quests.\n\n1. Earn 100 Epicurean's Awards from cooking dailies. Northrend Dalaran's faction cooking daily and eligible capital-city cooking dailies use this currency; check your currency balance before spending it on recipes or spices.\n\n2. Go to Derek Odds beside the Alliance kitchen (40.6, 65.8) or Misensi beside the Horde kitchen (70.2, 39.0) in Northrend Dalaran. Buy the CURRENT Chef's Hat toy (134020) for 100 awards.\n\n3. Check achievement credit from the purchase, then use the item to add it to your Toy Box. Merely wearing a chef-looking transmog item is not the purchase requirement.\n\n4. During Wrath Timewalking, check Auzin's current Small Spice Bag stock if you have spare Timewarped Badges: these bags can provide awards. Compare the vendor's live cost before buying, since the regular daily route works independently of this event.",
        stepCount = 4,
        waypoints = {
            { mapID = 125, x = 0.406, y = 0.6579999999999999, step = 2, label = "Derek Odds - Alliance Chef's Hat" },
            { mapID = 125, x = 0.7020000000000001, y = 0.39, step = 2, label = "Misensi - Horde Chef's Hat" },
            { mapID = 125, x = 0.5, y = 0.456, step = 4, label = "Auzin - optional Wrath Timewalking spice bags" },
        },
        tips = "Buying the hat awards the achievement and removes its normal currency-refund option. The old head-slot item was replaced by a toy.",
        sources = {
            "https://www.wowhead.com/achievement=3296#comments:id=2864839",
            "https://www.wowhead.com/achievement=3296#comments:id=5441688",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=3296",
        sourceURL = "https://www.wowhead.com/achievement=3296#comments",
        difficultyReason = "Earn and spend one hundred Epicurean's Awards on the Chef's Hat; regular income is limited by daily quests.",
        difficulty = "hard",
    },
    [3316] = {
        achievementId = 3316,
        name = "Herald of the Titans",
        category = "Raids",
        sourceType = "Achievement",
        source = "Herald of the Titans",
        acquisition = "Difficulty: Hard - Assemble a level-30 raid meeting Herald's equipment restrictions and defeat Algalon within those limits.\n\n1. Use a LEVEL 30 character and stop experience gains before preparing. The CURRENT Retail requirement is item level 41 or lower in every equipped slot; old level-80, item-level-107 or item-level-226 instructions predate later squishes. Check the in-game achievement text again before assembling the group.\n\n2. Prepare a group whose participating characters all meet that level and equipment limit. Audit weapons, off-hands, trinkets and profession-related equipment as well as armor. Prefer unambiguous eligible items; avoid equipping higher-level loot during the run. Recent successful Midnight reports used item level 40 or lower.\n\n3. Enter regular Ulduar at 41.6, 18.2 in Storm Peaks, clear Flame Leviathan and XT-002, and take the side passage in the Antechamber to the Celestial Planetarium. Use its console to open Algalon's room. A key and the old one-hour access timer are not required.\n\n4. Defeat Algalon with the eligible characters. Move out of Cosmic Smash, swap tanks as needed for Phase Punch, and arrange Big Bang survival: the group enters available black holes shortly before the cast finishes while a designated survivor remains outside with suitable protection. Do not stand on a black hole after being returned to the normal realm.\n\n5. Check the title achievement after the defeat. The ordinary max-level Algalon kill cannot award Herald. Recent solo reports use Infinitely Divisible Ooze on an eligible level-30 character, but that trinket is an alternative, not a requirement for the group route.",
        stepCount = 5,
        waypoints = {
            { mapID = 120, x = 0.41600000000000004, y = 0.182, step = 3, label = "Ulduar - regular raid entrance" },
            {
                mapID = 148,
                x = 0.792,
                y = 0.45799999999999996,
                step = 3,
                label = "Algalon - Celestial Planetarium",
                mapName = "The Antechamber of Ulduar",
            },
            {
                mapID = 148,
                x = 0.792,
                y = 0.45799999999999996,
                step = 4,
                label = "Eligible level-30 group; item level 41 maximum",
                mapName = "The Antechamber of Ulduar",
            },
        },
        tips = "Herald is still obtainable. A September 2026 reply also confirms preparing the route with a high-level friend, but the character and gear requirements must be met for Algalon itself. Remove questionable higher-level items from bags before the attempt as advised by the preparation thread.",
        sources = {
            "https://www.wowhead.com/achievement=3316#comments:id=5918538",
            "https://www.wowhead.com/achievement=3316#comments:id=6055051",
            "https://www.wowhead.com/achievement=3316#comments:id=6274124",
            "https://www.wowhead.com/achievement=3316#comments:id=6298260",
            "https://www.wowhead.com/achievement=3316#comments:id=6354056",
            "https://www.wowhead.com/achievement=3316#comments:id=6372630",
            "https://www.wowhead.com/achievement=3316#comments:id=6434335",
        },
        wowheadUrl = "https://www.wowhead.com/achievement=3316",
        sourceURL = "https://www.wowhead.com/achievement=3316#comments",
        difficultyReason = "Assemble a level-30 raid meeting Herald's equipment restrictions and defeat Algalon within those limits.",
        difficulty = "hard",
    },
}

